# Initially generated by GitHub Copilot.
"""Inventory small-letter nodes in MAM-simple JSON, including alternatives and notes."""

from mb_cmn import file_io
from mb_cmn import mam_simple_json

_OUTPUT_PATH = "py-examples-out/letter-small-job.txt"

# This is an annotation inventory. Every declared alternative and note is included;
# it does not select a running-text edition. Unknown node types always raise.
_FORM_CHILDREN = {"text", "lp-legarmeih", "lp-paseq", "silluq-before-meteg"}
_CONTAINER_CHILDREN = {
    "kq": {"kq-k", "kq-q"},
    "kq-k": {"slh-word"},
    "kq-q": {"text", "lp-legarmeih", "lp-paseq"},
    "kq-trivial": {"text", "lp-legarmeih"},
    "slh-word": {
        "text",
        "letter-small",
        "letter-large",
        "letter-hung",
        "lp-legarmeih",
        "lp-paseq",
    },
    "scrdfftar": {"sdt-target", "sdt-note"},
    "sdt-target": {"text", "slh-word", "silluq-before-meteg", "spi-pe2"},
    "sdt-note": {"text", "slh-word"},
    "cant-all-three": {"cant-combined", "cant-alef", "cant-bet"},
    "cant-combined": _FORM_CHILDREN,
    "cant-alef": _FORM_CHILDREN,
    "cant-bet": _FORM_CHILDREN,
}
_TEXT_OR_CHILDREN = {
    "kq-k",
    "kq-q",
    "kq-trivial",
    "sdt-target",
    "sdt-note",
    "cant-combined",
    "cant-alef",
    "cant-bet",
}
_TEXT_LEAVES = {
    "text",
    "letter-small",
    "letter-large",
    "letter-hung",
    "silluq-before-meteg",
    "kq-k-velo-q",
    "kq-q-velo-k",
    "good-ending",
}
_BARE_LEAVES = {
    "lp-legarmeih",
    "lp-paseq",
    "implicit-maqaf",
    "shirah-space",
    "spi-invnun",
    "spi-pe2",
    "spi-pe3",
    "spi-samekh2",
    "spi-samekh3",
    "kq-k-velo-q-maq",
}
_VERSE_CHILDREN = {
    "text",
    "silluq-before-meteg",
    "kq",
    "kq-trivial",
    "slh-word",
    "scrdfftar",
    "cant-all-three",
    "good-ending",
    "kq-k-velo-q",
    "kq-q-velo-k",
    *_BARE_LEAVES,
}


def _check_container(node, attrs, children):
    kind = node["type"]
    child_types = [child["type"] for child in children]
    if kind == "verse":
        required = {"osisID"}
        allowed = {
            "osisID",
            "text",
            "starts-with-sampe",
            "ends-with-sampe",
            "contents-corresponds-to",
            "osisID-of-MAM-src",
        }
        allowed_children = _VERSE_CHILDREN
    else:
        required = set()
        allowed = {"text"} if kind in _TEXT_OR_CHILDREN else set()
        allowed_children = _CONTAINER_CHILDREN[kind]
        if kind == "slh-word":
            required = allowed = {f"slhw-desc-{index}" for index in range(4)}
        elif kind == "scrdfftar":
            required = allowed = {"sdt-starpos"}
        elif kind == "kq":
            allowed = {"class"}
    if (
        not required <= set(attrs) <= allowed
        or not set(child_types) <= allowed_children
    ):
        raise ValueError(f"Unexpected {kind} inventory shape: {node}")
    if kind == "kq":
        if sorted(child_types) != ["kq-k", "kq-q"] or attrs.get("class") not in (
            None,
            "sep-maqaf",
        ):
            raise ValueError(f"Unexpected ketiv/qere pair: {node}")
    elif kind == "cant-all-three":
        if child_types != ["cant-combined", "cant-alef", "cant-bet"]:
            raise ValueError(f"Unexpected cantillation alternatives: {node}")
    elif kind == "scrdfftar":
        if child_types != ["sdt-target", "sdt-note"] or attrs["sdt-starpos"] not in (
            "before-word",
            "after-word",
        ):
            raise ValueError(f"Unexpected scroll-difference note: {node}")
    elif kind == "kq-k" and "text" not in attrs and child_types != ["slh-word"]:
        raise ValueError(f"Unexpected ketiv contents: {node}")
    elif (
        kind == "kq-trivial"
        and "text" not in attrs
        and child_types != ["text", "lp-legarmeih"]
    ):
        raise ValueError(f"Unexpected trivial ketiv/qere contents: {node}")
    if (
        kind != "verse"
        and "text" not in attrs
        and not children
        and not (
            kind in {"sdt-target", "sdt-note", "cant-combined", "cant-alef", "cant-bet"}
            and "contents" in node
        )
    ):
        raise ValueError(f"Empty {kind} inventory container: {node}")


def _small_letters(node):
    attrs = mam_simple_json.attributes(node)
    children = mam_simple_json.children(node)
    kind = node["type"]
    if kind in _CONTAINER_CHILDREN or kind == "verse":
        _check_container(node, attrs, children)
        for child in children:
            yield from _small_letters(child)
    elif kind in _TEXT_LEAVES:
        expected = (
            {"text", "letters-with-silluq"}
            if kind == "silluq-before-meteg"
            else {"text"}
        )
        if set(attrs) != expected or children:
            raise ValueError(f"Unexpected text leaf: {node}")
        if kind == "letter-small":
            yield node["text"]
    elif kind in _BARE_LEAVES:
        classes = {
            "spi-invnun": (None, "including-trailing-space"),
            "spi-samekh3": (None, "nu10-invnun-neighbor"),
        }
        if (
            set(attrs) - {"class"}
            or attrs.get("class") not in classes.get(kind, (None,))
            or children
        ):
            raise ValueError(f"Unexpected bare leaf: {node}")
    else:
        raise ValueError(f"Unhandled MAM-simple type {kind}")


def _write_rows(rows, out_fp):
    out_fp.writelines(rows)


def almost_main(json_path, output_path=_OUTPUT_PATH):
    """Find small-letter nodes in the given JSON book."""
    root = mam_simple_json.read_book_group(json_path)
    rows = []
    for verse in mam_simple_json.verses(root):
        for text in _small_letters(verse):
            rows.append(f"{verse['osisID']}\t{text}\n")
    file_io.with_tmp_openw(output_path, {}, _write_rows, rows)
